// Helper to get merged projects list
function getProjects() {
    const deletedIds = JSON.parse(localStorage.getItem('ariya_deleted_projects')) || [];
    const customProjects = JSON.parse(localStorage.getItem('ariya_projects')) || [];
    
    let list = JSON.parse(JSON.stringify(defaultProjects));
    customProjects.forEach(cp => {
        const idx = list.findIndex(p => p.id === cp.id);
        if (idx !== -1) {
            list[idx] = cp;
        } else {
            list.push(cp);
        }
    });
    return list.filter(p => !deletedIds.includes(p.id));
}

// Initialize State
let projects = getProjects();
let settings = JSON.parse(localStorage.getItem('ariya_settings')) || defaultSettings;
let isLoggedIn = false;
let currentBgIndex = 0;

// DOM Elements
const projectsGrid = document.getElementById('projects-grid');
const adminBtn = document.getElementById('admin-btn');
const adminModal = document.getElementById('admin-modal');
const closeModal = document.querySelector('.close-modal');
const loginForm = document.getElementById('login-form');

// Functions
function renderProjects() {
    projectsGrid.innerHTML = '';
    projects.forEach(project => {
        const card = document.createElement('div');
        card.className = 'project-card animate-up';
        
        let mediaHtml = '';
        if (project.type === 'video') {
            mediaHtml = `<video class="project-media" src="${project.url}" muted loop onmouseover="this.play()" onmouseout="this.pause()"></video>`;
        } else {
            mediaHtml = `<img src="${project.url}" alt="${project.title}" class="project-media">`;
        }

        card.innerHTML = `
            <a href="project.html?id=${project.id}" target="_blank" style="text-decoration: none; color: inherit; display: block;">
                ${mediaHtml}
                <div class="project-info">
                    <h3>${project.title}</h3>
                    <p>${project.description.substring(0, 100)}${project.description.length > 100 ? '...' : ''}</p>
                </div>
            </a>
            ${isLoggedIn ? `<div style="padding: 0 1.5rem 1.5rem 1.5rem;"><button onclick="deleteProject(${project.id})" class="btn-outline" style="padding: 0.3rem 0.8rem; font-size: 0.8rem;">Delete</button></div>` : ''}
        `;
        projectsGrid.appendChild(card);
    });
}

function applySettings() {
    // Logo
    const logoImg = document.getElementById('site-logo');
    if (logoImg) {
        if (settings.logo) {
            logoImg.src = settings.logo;
            logoImg.style.display = 'block';
        } else {
            logoImg.style.display = 'none';
        }
    }

    // Slogan
    const sloganEl = document.getElementById('hero-slogan');
    if (sloganEl && settings.slogan) {
        sloganEl.innerHTML = settings.slogan.replace('Future', '<span class="gradient-text">Future</span>');
    }

    // Contact
    const emailEl = document.getElementById('contact-email');
    const phoneEl = document.getElementById('contact-phone');
    if (emailEl) emailEl.textContent = settings.email;
    if (phoneEl) phoneEl.textContent = settings.phone;

    // Background Slideshow
    if (document.getElementById('hero-bg-container')) {
        renderSlideshow();
    }
}

function renderSlideshow() {
    const container = document.getElementById('hero-bg-container');
    if (!container) return;
    
    container.innerHTML = '';
    
    if (settings.backgrounds && settings.backgrounds.length > 0) {
        settings.backgrounds.forEach((bg, index) => {
            const div = document.createElement('div');
            div.className = `hero-bg-image ${index === 0 ? 'active' : ''}`;
            div.style.backgroundImage = `url(${bg})`;
            container.appendChild(div);
        });

        if (settings.backgrounds.length > 1) {
            startSlideshow();
        }
    }
}

let slideInterval;
function startSlideshow() {
    clearInterval(slideInterval);
    slideInterval = setInterval(() => {
        const images = document.querySelectorAll('.hero-bg-image');
        images[currentBgIndex].classList.remove('active');
        currentBgIndex = (currentBgIndex + 1) % images.length;
        images[currentBgIndex].classList.add('active');
    }, 5000);
}

function login() {
    const user = document.getElementById('admin-username').value;
    const pass = document.getElementById('admin-password').value;

    if (user === 'admin' && pass === 'password123') {
        localStorage.setItem('ariya_logged_in', 'true');
        
        // Clear inputs
        document.getElementById('admin-username').value = '';
        document.getElementById('admin-password').value = '';
        
        // Hide modal
        adminModal.style.display = 'none';
        
        // Open Admin Interface in New Tab
        window.open('admin.html', '_blank');
        
        alert('Welcome! The Admin Interface is opening in a new tab.');
    } else {
        alert('Access Denied: Invalid Username or Password');
    }
}

// Note: Dashboard management (addProject, deleteProject, etc) is now handled in admin.html

function deleteProject(id) {
    if (!isLoggedIn) return;
    if (confirm('Delete this project?')) {
        let deletedIds = JSON.parse(localStorage.getItem('ariya_deleted_projects')) || [];
        if (!deletedIds.includes(id)) {
            deletedIds.push(id);
            localStorage.setItem('ariya_deleted_projects', JSON.stringify(deletedIds));
        }
        let customProjects = JSON.parse(localStorage.getItem('ariya_projects')) || [];
        customProjects = customProjects.filter(p => p.id !== id);
        localStorage.setItem('ariya_projects', JSON.stringify(customProjects));
        
        projects = getProjects();
        renderProjects();
    }
}

// Event Listeners
if (adminBtn) {
    adminBtn.addEventListener('click', () => {
        if (loginForm) loginForm.classList.remove('hidden');
        if (adminModal) adminModal.style.display = 'flex';
    });
}
if (closeModal) {
    closeModal.addEventListener('click', () => {
        if (adminModal) adminModal.style.display = 'none';
    });
}
window.onclick = (e) => { 
    if (adminModal && e.target == adminModal) {
        adminModal.style.display = 'none'; 
    }
};

// Initial Load
applySettings();

if (document.getElementById('projects-grid')) {
    renderProjects();
}
